package com.powercms.cms.delivery;
import com.powercms.cms.content.repo.ContentItemRepository; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.mock;
class PreviewTokenServiceTest { private PreviewTokenService service(){var s=new PreviewTokenService(mock(ContentItemRepository.class));s.setSigningSecret("test-secret-that-is-at-least-thirty-two-characters");return s;} @Test void submissionTokenRoundTripsAndBindsClaims(){var s=service();UUID site=UUID.randomUUID();String token=s.issueSubmissionToken(site,"contact","public",60);assertTrue(s.validateSubmissionToken(token,site,"contact","public"));assertFalse(s.validateSubmissionToken(token,UUID.randomUUID(),"contact","public"));assertFalse(s.validateSubmissionToken(token,site,"other","public"));assertFalse(s.validateSubmissionToken(token,site,"contact","admin"));} @Test void tamperedTokenIsRejected(){var s=service();UUID site=UUID.randomUUID();String token=s.issueSubmissionToken(site,"contact","public",60);assertFalse(s.validateSubmissionToken(token.substring(0,token.length()-1)+(token.endsWith("A")?"B":"A"),site,"contact","public"));assertFalse(s.validateSubmissionToken("not-a-token",site,"contact","public"));}}
